import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

function ListingDetails() {
  const location = useLocation();
  const navigate = useNavigate();
  const listing = location.state?.listing;
  const [mainImage, setMainImage] = useState(listing?.images[0]);

  if (!listing) {
    return <p>No details available.</p>;
  }

  return (
    <div className="container mx-auto px-4 py-6">
      {/* Back Button */}
      <button
        onClick={() => navigate(-1)}
        className="bg-gray-500 text-white px-4 py-2 rounded hover:bg-gray-600 mb-6"
      >
        Back to Results
      </button>

      {/* Listing Details */}
      <div className="bg-white border rounded-lg shadow-md">
        {/* Header Section */}
        <div className="relative">
          <img
            src={mainImage}
            alt={listing.title}
            className="w-full h-96 object-cover rounded-t-lg"
          />
          <div className="absolute top-4 left-4 bg-yellow-500 text-white px-2 py-1 rounded">
            Elite
          </div>
        </div>

        {/* Details Section */}
        <div className="p-6">
          <h1 className="text-3xl font-bold mb-4">{listing.title}</h1>
          <p className="text-gray-600 mb-2 font-medium text-lg">{listing.location}</p>
          <p className="text-red-500 text-2xl font-semibold mb-6">{listing.price}</p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <h2 className="text-lg font-semibold mb-2">Details</h2>
              <p className="text-sm text-gray-700">Year: {listing.year}</p>
              <p className="text-sm text-gray-700">Condition: {listing.condition}</p>
              <p className="text-sm text-gray-700">Added: {listing.added}</p>
            </div>
            <div>
              <h2 className="text-lg font-semibold mb-2">Contact</h2>
              <button className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 w-full mb-2">
                Call
              </button>
              <button className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600 w-full">
                WhatsApp
              </button>
            </div>
          </div>
        </div>

        {/* Description Section */}
        <div className="p-6">
          <h2 className="text-lg font-semibold mb-2">Description</h2>
          <p className="text-sm text-gray-700">{listing.description}</p>
        </div>

        {/* Additional Images Section */}
        {listing.images.length > 1 && (
          <div className="p-6">
            <h2 className="text-lg font-semibold mb-4">Gallery</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
              {listing.images.slice(1).map((image, index) => (
                <img
                  key={index}
                  src={image}
                  alt={`Additional Image ${index + 1}`}
                  className="w-full h-40 object-cover rounded-md cursor-pointer"
                  onClick={() => setMainImage(image)}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default ListingDetails;
